import { app } from 'electron'
import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { join } from 'node:path'
import { createPublicKey, verify } from 'node:crypto'

/**
 * Pro license gate — self-signed Ed25519 keys, fully offline.
 *
 * Keys are generated by scripts/generate-license.mjs (or a purchase
 * webhook) and look like:
 *   K8SD-<base64url(payload)>.<base64url(signature)>
 * Payload: {"email":"…","exp?":"ISO date"}
 *
 * The private key never ships; only the public key below is embedded.
 * This source is public — a determined user could patch the check or
 * sign their own key. What you sell is the signed build + updates,
 * same as every open-core desktop app.
 *
 * Dev override: K8S_DESKTOP_PRO=1 in the environment.
 */

const PUBLIC_KEY_B64 = 'MCowBQYDK2VwAyEAsnKi8Qbgrb/T7faSwnBc28HRpIXCjl0rSt2WdDL2uxM='

export interface LicenseState {
  pro: boolean
  key?: string
  email?: string
  expiresAt?: string
  error?: string
}

interface StoredLicense {
  key: string
  email?: string
  expiresAt?: string
  validatedAt: string
}

function licenseFile(): string {
  return join(app.getPath('userData'), 'license.json')
}

async function readStored(): Promise<StoredLicense | null> {
  try {
    return JSON.parse(await readFile(licenseFile(), 'utf8'))
  } catch {
    return null
  }
}

async function storeLicense(l: StoredLicense | Record<string, never>): Promise<void> {
  await mkdir(app.getPath('userData'), { recursive: true })
  await writeFile(licenseFile(), JSON.stringify(l, null, 2))
}

function verifyKey(key: string): { email?: string; expiresAt?: string } | null {
  const m = /^K8SD-([A-Za-z0-9_-]+)\.([A-Za-z0-9_-]+)$/.exec(key.trim())
  if (!m) return null
  const [, payloadB64, sigB64] = m
  try {
    const sig = Buffer.from(sigB64, 'base64url')
    const pub = createPublicKey({
      key: Buffer.from(PUBLIC_KEY_B64, 'base64'),
      format: 'der',
      type: 'spki'
    })
    if (!verify(null, Buffer.from(payloadB64), pub, sig)) return null
    const data = JSON.parse(
      Buffer.from(payloadB64, 'base64url').toString('utf8')
    ) as { email?: string; exp?: string }
    if (data.exp && new Date(data.exp).getTime() < Date.now()) return null
    return { email: data.email, expiresAt: data.exp }
  } catch {
    return null
  }
}

export async function licenseStatus(): Promise<LicenseState> {
  if (process.env.K8S_DESKTOP_PRO === '1' || process.env.K8S_DESKTOP_PRO === 'true') {
    return { pro: true, email: 'dev-override' }
  }
  const stored = await readStored()
  if (!stored?.key) return { pro: false }
  const v = verifyKey(stored.key)
  if (!v) {
    await storeLicense({})
    return { pro: false }
  }
  return { pro: true, email: v.email, expiresAt: v.expiresAt, key: `${stored.key.slice(0, 14)}…` }
}

export async function activateLicense(key: string): Promise<LicenseState> {
  const trimmed = key.trim()
  const v = verifyKey(trimmed)
  if (!v) {
    return { pro: false, error: 'License key not valid or expired' }
  }
  await storeLicense({
    key: trimmed,
    email: v.email,
    expiresAt: v.expiresAt,
    validatedAt: new Date().toISOString()
  })
  return { pro: true, email: v.email, expiresAt: v.expiresAt, key: `${trimmed.slice(0, 14)}…` }
}

export async function deactivateLicense(): Promise<void> {
  await storeLicense({})
}
